//! 🧳️ A typed primary and every independent refusal keep their original backing through settlement.
use super::*;
use semio_framework_value::{RetainedCloneProgress,RetireOwned,ToValue,ValueError,ValueRefusalKind};
use semio_framework_value_native_owned::OriginalReceivingPrimary;
use semio_framework_value::retirement::controlled::ControlledRetirement;
use semio_framework_value::ErasedSnapshotRetirement;
fn close<T:RetireOwned>(original:T,g:semio_framework_value::RetainedCloneGrant,maximum:u64){let mut owner=ControlledRetirement::new(original).ok().unwrap();for _ in 0..maximum{if owner.terminal_is_empty(){break}let mut actual=None;let mut effect=semio_framework_value::RetainedAllocationEffect::new(g,u64::MAX,&mut actual);let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||owner.step(&mut effect));let p=result.unwrap().progress();assert_eq!((born,released),(p.retained_capacity_bytes,p.released_bytes));}assert!(owner.terminal_is_empty());}
fn receive_wire(wire:semio_framework_value::DslValue)->NativeSnapshotFailure{
 use semio_framework_value::{NativeReceive,NativeReceiver,RetainedAllocationEffect,RetainedCloneGrant,RetirementDemand};use semio_framework_value_native_owned::native_decoding::{NativeDecodeControl,NativeDecodeConstructionRecipient,NativeDecodeRetirementRecipient,NativeDecodeWorkRecipient,NativeDecodeWorkIssuer};
 struct Work;impl NativeDecodeWorkRecipient for Work{fn available_work(&mut self,observed:u64)->Result<u64,ValueError>{let limit:u64=10000000;limit.checked_sub(observed).ok_or_else(||ValueError::invariant("native observed work exceeds its actual finite scope"))}fn admits(&mut self,observed:u64,additional:u64)->Result<bool,ValueError>{Ok(observed.checked_add(additional).is_some_and(|total|total<=10000000))}}
 struct Physical{grant:RetainedCloneGrant,submitted:RetainedCloneProgress}impl NativeDecodeConstructionRecipient for Physical{fn submitted(&self)->RetainedCloneProgress{self.submitted}fn grant(&mut self,_:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{Ok(self.grant)}fn accept(&mut self,_:RetainedCloneGrant,progress:RetainedCloneProgress)->Result<(),ValueError>{self.submitted=self.submitted.checked_add(progress)?;Ok(())}}
 let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:1048576,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:4096};let mut wallet=();let mut source=semio_framework_value_testing_admission::capture(wire,&mut wallet,|_|grant,|_,_,_,_,_|{});
 let mut observer=|_|true;let mut retirement=NativeDecodeRetirementRecipient::new();let mut native=NativeDecodeControl::new(1<<30,&mut observer);native.install_retirement_recipient(&mut retirement).unwrap();let mut physical=Physical{grant,submitted:Default::default()};let mut issuer=semio_framework_value_native_owned::native_decoding::NativeConstructionRecipientIssuer::new();let mut physical_loan=issuer.loan(&mut physical);let mut work=Work;let mut work_issuer=NativeDecodeWorkIssuer::new();let mut work_loan=work_issuer.loan(&mut work);let mut receiver=<NativeSnapshotFailure as NativeReceive<semio_framework_value::DslValue>>::receiver();
 native.with_work_recipient(&mut work_loan,|native|{
  for _ in 0..1000000{if receiver.output_ready(){break}let turn=native.with_construction_recipient(&mut physical_loan,|native|Ok::<_,ValueError>(receiver.advance(source.borrow(),native,grant.maximum_copy_bytes,grant)))?;assert!(turn.result.unwrap().progress().fits(grant));}
  assert!(receiver.output_ready());let output=receiver.take(grant).result.unwrap().unwrap().0;receiver.begin_close();
  for _ in 0..1000000{if receiver.terminal_is_empty(){break}let turn=if receiver.requires_original_birth(){native.with_retirement::<_,ValueError>(grant,|loan|loan.with_original_close(|original|Ok(receiver.close_original_birth_step(original,grant))))?}else{let mut actual=None;let mut effect=RetainedAllocationEffect::new(grant,u64::MAX,&mut actual);if receiver.requires_original_control(){native.with_retirement::<_,ValueError>(grant,|loan|loan.with_original_close(|original|Ok(receiver.close_original_step(original,&mut effect))))?}else{receiver.close_step(&mut effect)}};assert!(turn.result.unwrap().progress().fits(grant));}assert!(receiver.terminal_is_empty());
  for _ in 0..1000000{if source.terminal_is_empty(){break}let mut actual=None;let turn=source.close_step(&mut RetainedAllocationEffect::new(grant,u64::MAX,&mut actual));assert!(turn.result.unwrap().progress().fits(grant));}assert!(source.terminal_is_empty());
  while native.has_retirement_owner()||native.has_retirement_failure_storage(){native.close_retirement_recipient(grant).result.unwrap();}Ok::<_,ValueError>(output)
 }).unwrap()
}
#[test]
fn original_allocation_outcomes_keep_all_independent_causes_and_reject_replacement(){
 let f:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/📦️allocation.json")).unwrap();let messages=f["messages"].as_array().unwrap();let error=|index:usize|ValueError::new(ValueRefusalKind::Canceled,messages[index].as_str().unwrap().to_owned());let grant=semio_framework_value::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:4096};
 for encoding in [true,false]{let primary=error(0);let work=error(1);let receipt=error(2);let original_pointers=[primary.message.as_ptr(),work.message.as_ptr(),receipt.message.as_ptr()];let mut failure=NativeSnapshotFailure::primary_with_work(primary,work).with_receipt_refusal(receipt);let allocation=if encoding{NativeSnapshotAllocationFailure::Encode(semio_framework_value::native_encoding::NativeEncodeAllocationOutcome{admitted:false,forwarded_quote:Some(error(4).into()),scoped_quote:Some(error(5).into()),request:Some(semio_framework_value::native_encoding::NativeAllocationRequest{bytes:f["request"]["bytes"].as_u64().unwrap() as usize,owned_bytes:f["request"]["ownedBytes"].as_u64().unwrap() as usize,next_owned_bytes:f["request"]["nextOwnedBytes"].as_u64().unwrap() as usize,maximum_bytes:f["request"]["maximumBytes"].as_u64().unwrap() as usize}),primary:Some(error(0)),extent_refusal:Some(error(3)),forwarded_refusal:Some(error(4).into()),scoped_refusal:Some(error(5).into()),actual:Some(f["actual"].as_u64().unwrap()as usize)})}else{NativeSnapshotAllocationFailure::Decode(semio_framework_value_native_owned::native_decoding::NativeDecodeAllocationOutcome{admitted:false,quote_refusal:Some(error(4).into()),request:Some(semio_framework_value_native_owned::native_decoding::NativeAllocationRequest{bytes:f["request"]["bytes"].as_u64().unwrap() as usize,owned_bytes:f["request"]["ownedBytes"].as_u64().unwrap() as usize,next_owned_bytes:f["request"]["nextOwnedBytes"].as_u64().unwrap() as usize,maximum_bytes:f["request"]["maximumBytes"].as_u64().unwrap() as usize}),primary:Some(error(0)),extent_refusal:Some(error(3)),settlement_refusal:Some(error(6).into()),actual:Some(f["actual"].as_u64().unwrap()as usize)})};failure=failure.with_allocation(allocation).unwrap();let repeated=NativeSnapshotAllocationFailure::Decode(semio_framework_value_native_owned::native_decoding::NativeDecodeAllocationOutcome{request:None,admitted:false,quote_refusal:None,primary:Some(error(7)),extent_refusal:None,settlement_refusal:None,actual:None});let repeated_pointer=match &repeated{NativeSnapshotAllocationFailure::Decode(value)=>value.primary.as_ref().unwrap().message.as_ptr(),_=>unreachable!()};let(failure,repeated)=failure.with_allocation(repeated).unwrap_err();let Some(NativeSnapshotCause::Value(primary))=failure.cause()else{panic!("original value cause absent")};assert_eq!(primary.message.as_ptr(),original_pointers[0]);assert_eq!(failure.work_refusal().unwrap().message.as_ptr(),original_pointers[1]);assert_eq!(failure.receipt_refusal().unwrap().message.as_ptr(),original_pointers[2]);let NativeSnapshotAllocationFailure::Decode(repeated_value)=&repeated else{unreachable!()};assert_eq!(repeated_value.primary.as_ref().unwrap().message.as_ptr(),repeated_pointer);
  let mut observe=|_|true;let mut encoder=semio_framework_value::NativeEncodeControl::new(grant.maximum_capacity_bytes,&mut observe);let wire=failure.to_value_controlled(&mut encoder).unwrap();let json=serde_json::to_value(&wire).unwrap();let allocation=&json["allocation"];assert_eq!(allocation["type"],if encoding{"encode"}else{"decode"});assert_eq!(allocation["actual"],f["actual"]);assert_eq!(allocation["primary"]["message"],messages[0]);assert_eq!(allocation["extentRefusal"]["message"],messages[3]);if encoding{assert_eq!(allocation["forwardedRefusal"]["message"],messages[4]);assert_eq!(allocation["scopedRefusal"]["message"],messages[5]);}else{assert_eq!(allocation["settlementRefusal"]["message"],messages[6]);}drop(encoder);let decoded=receive_wire(wire);assert_eq!(decoded,failure);close(decoded,grant,f["maximumTurns"].as_u64().unwrap());close(failure,grant,f["maximumTurns"].as_u64().unwrap());close(repeated,grant,f["maximumTurns"].as_u64().unwrap());
 }
}
#[test]
fn native_snapshot_settlement_keeps_nonclone_primary_context_and_repeated_owner(){
 let(_,born,released)=semio_framework_trace_memory_testing::observe_backing(||{let bytes=std::hint::black_box(vec![0u8;73]);std::hint::black_box(&bytes);drop(bytes);});assert_eq!((born,released),(73,73));
 let f:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let p:RetainedCloneProgress=serde_json::from_value(f["progress"].clone()).unwrap();let messages=f["messages"].as_array().unwrap();let owned=|index:usize|ValueError::new(ValueRefusalKind::InvalidValue,messages[index].as_str().unwrap().to_owned());
 let primary=OriginalReceivingPrimary{retirement_failure:None,work_refusal:None,work_overrun:None,primary:Some(owned(0)),quote_refusal:Some(owned(1)),allocation_refusal:Some(owned(2)),allocation_failure:None,native_allocation:None,receipt_refusal:None,progress:p};let original=NativeSnapshotFailure::from(primary).with_context_refusal(owned(3));let settlement=owned(4);let repeated=owned(5);
 let pointers=|failure:&NativeSnapshotFailure|{let primary=failure.receiving_primary().unwrap();[primary.primary.as_ref().unwrap().message.as_ptr(),primary.quote_refusal.as_ref().unwrap().message.as_ptr(),primary.allocation_refusal.as_ref().unwrap().message.as_ptr(),failure.context_refusal().unwrap().message.as_ptr()]};let originals=pointers(&original);let settlement_pointer=settlement.message.as_ptr();let repeated_pointer=repeated.message.as_ptr();
 let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||original.with_settlement_refusal(settlement));assert_eq!((born,released),(f["expected"]["foldAllocationBytes"].as_u64().unwrap()as usize,f["expected"]["foldReleaseBytes"].as_u64().unwrap()as usize));assert_eq!(result.is_ok(),f["expected"]["accepted"].as_bool().unwrap());let original=result.unwrap();assert_eq!(pointers(&original),originals);assert_eq!(original.settlement_refusal().unwrap().message.as_ptr(),settlement_pointer);assert_eq!(original.retained_progress(),p);
 let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||original.with_settlement_refusal(repeated));assert_eq!((born,released),(0,0));assert_eq!(result.is_ok(),f["expected"]["repeatAccepted"].as_bool().unwrap());let(original,repeated)=result.unwrap_err();assert_eq!(pointers(&original),originals);assert_eq!(original.settlement_refusal().unwrap().message.as_ptr(),settlement_pointer);assert_eq!(repeated.message.as_ptr(),repeated_pointer);assert_eq!(original.retained_progress(),p);assert_eq!(original.message(),messages[0].as_str().unwrap());assert_eq!(original.receipt_refusal(),None);
 let g=serde_json::from_value(f["closeGrant"].clone()).unwrap();let maximum=f["maximumTurns"].as_u64().unwrap();close(original,g,maximum);close(repeated,g,maximum);
}

#[test]
fn measured_child_work_survives_its_original_refusal(){
 use semio_framework_value_native_owned::native_decoding::{NativeDecodeControl,NativeDecodeWorkRecipient};
 struct Loan{remaining:u64}
 impl NativeDecodeWorkRecipient for Loan{fn available_work(&mut self,observed:u64)->Result<u64,ValueError>{let limit:u64=self.remaining;limit.checked_sub(observed).ok_or_else(||ValueError::invariant("native observed work exceeds its actual finite scope"))}fn admits(&mut self,observed:u64,additional:u64)->Result<bool,ValueError>{Ok(observed.checked_add(additional).is_some_and(|total|total<=self.remaining))}}
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/📏️measured-work.json")).unwrap();
 for case in fixture["cases"].as_array().unwrap(){let allowance=case["allowance"].as_u64().unwrap();
  let mut accept=|_|true;let mut native=NativeDecodeControl::new(0,&mut accept);let mut loan=Loan{remaining:allowance};
  let turn=native.with_work_recipient(&mut loan,|native|Ok::<_,ValueError>(crate::native_snapshot_turn(|work|{
   work.measured(native,|native|{if !native.prepare_work(fixture["admitted"].as_u64().unwrap())?{return Err(ValueError::literal(ValueRefusalKind::WorkLimit,"fixture loan denied"))}native.commit_work(fixture["admitted"].as_u64().unwrap())?;Err::<(),_>(ValueError::literal(ValueRefusalKind::Canceled,"fixture child refused"))})
  }))).unwrap();
  assert_eq!(turn.work,allowance);assert_eq!(native.actual_work(),allowance);let failure=turn.result.unwrap_err();
  assert_eq!(serde_json::json!({"allowance":allowance,"work":turn.work,"kind":failure.kind().as_str()}),*case);
  if allowance!=0{assert_eq!(failure.kind().as_str(),fixture["expectedKind"].as_str().unwrap())}
  close(failure,semio_framework_value::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:4096},4096);
 }
}

#[test]
fn original_work_post_keeps_operation_and_repeat_owners(){
 let f:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🛠️work-post.json")).unwrap();let owned=|name:&str|ValueError::new(ValueRefusalKind::Canceled,f[name].as_str().unwrap().to_owned());let sole=NativeSnapshotFailure::work_post(owned("work"));assert!(sole.cause().is_none());assert_eq!(sole.work_refusal().unwrap().message.as_ref(),f["work"].as_str().unwrap());let sole_grant=semio_framework_value::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:4096};close(sole,sole_grant,4096);let primary=owned("primary");let work=owned("work");let repeat=owned("repeat");let primary_pointer=primary.message.as_ptr();let work_pointer=work.message.as_ptr();let repeat_pointer=repeat.message.as_ptr();
 let failure=NativeSnapshotFailure::primary_with_work(primary,work);assert_eq!(failure.message(),f["primary"].as_str().unwrap());assert_eq!(failure.work_refusal().unwrap().message.as_ptr(),work_pointer);let(failure,repeat)=failure.with_work_post(repeat).unwrap_err();assert_eq!(failure.message().as_ptr(),primary_pointer);assert_eq!(failure.work_refusal().unwrap().message.as_ptr(),work_pointer);assert_eq!(repeat.message.as_ptr(),repeat_pointer);
 let grant=semio_framework_value::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:4096};let mut observe=|_|true;let mut encoder=semio_framework_value::NativeEncodeControl::new(grant.maximum_capacity_bytes,&mut observe);let encoded=failure.to_value_controlled(&mut encoder).unwrap();let semio_framework_value::DslValue::Object(fields)=&encoded else{panic!("failure wire is an object")};assert!(fields.iter().any(|(name,value)|name=="workRefusal"&&!matches!(value,semio_framework_value::DslValue::Null)));drop(encoder);close(encoded,grant,4096);close(failure,grant,4096);close(repeat,grant,4096);
}

#[test]
fn original_retirement_dual_cause_moves_into_snapshot_failure_without_allocation(){
 let (_,born,released)=semio_framework_trace_memory_testing::observe_backing(||{let bytes=std::hint::black_box(vec![0u8;73]);std::hint::black_box(&bytes);drop(bytes)});assert_eq!((born,released),(73,73));
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let progress:RetainedCloneProgress=serde_json::from_value(fixture["progress"].clone()).unwrap();let messages=fixture["messages"].as_array().unwrap();let primary=ValueError::new(ValueRefusalKind::InvalidValue,messages[0].as_str().unwrap().to_owned()).with_retained_progress(progress);let work=ValueError::new(ValueRefusalKind::Canceled,messages[1].as_str().unwrap().to_owned());let pointers=(primary.message.as_ptr(),work.message.as_ptr());let original=semio_framework_value::OriginalRetirementFailure::from_primary_and_work(primary,work);
 let(failure,born,released)=semio_framework_trace_memory_testing::observe_backing(||NativeSnapshotFailure::from(original));assert_eq!((born,released),(0,0));assert_eq!(failure.message().as_ptr(),pointers.0);assert_eq!(failure.work_refusal().unwrap().message.as_ptr(),pointers.1);assert_eq!(failure.retained_progress(),progress);let grant=semio_framework_value::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:4096};close(failure,grant,4096);
}

#[test]
fn original_retirement_cause_keeps_all_four_owned_failures(){
 let f:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/♻️retirement.json")).unwrap();let value=|name:&str|ValueError::new(ValueRefusalKind::Canceled,f[name].as_str().unwrap().to_owned());let primary=value("innerPrimary");let work=value("innerWork");let receipt=value("innerReceipt");let allocation=value("innerAllocation");let pointers=[primary.message.as_ptr(),work.message.as_ptr(),receipt.message.as_ptr(),allocation.message.as_ptr()];
 let original=semio_framework_value::OriginalRetirementFailure::from_causes(Some(primary),Some(work),Some(receipt),Some(allocation.into()));let failure=NativeSnapshotFailure::from(original);let retired=failure.retirement_failure().unwrap();assert_eq!(retired.primary().unwrap().message.as_ptr(),pointers[0]);assert_eq!(retired.work_refusal().unwrap().message.as_ptr(),pointers[1]);assert_eq!(retired.receipt_refusal().unwrap().message.as_ptr(),pointers[2]);assert_eq!(retired.allocation_refusal().unwrap().owned().unwrap().message.as_ptr(),pointers[3]);let grant=semio_framework_value::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:4096};close(failure,grant,4096);
}

#[test]
fn nested_retirement_projection_obeys_original_source_depth_and_json_oracle(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/♻️retirement.json")).unwrap();let value=|name:&str|ValueError::new(ValueRefusalKind::Canceled,fixture[name].as_str().unwrap().to_owned());let inner=semio_framework_value::OriginalRetirementFailure::from_causes(Some(value("innerPrimary")),Some(value("innerWork")),Some(value("innerReceipt")),Some(value("innerAllocation").into())).with_retained_progress(RetainedCloneProgress{copied_bytes:7,..Default::default()});let mut actual=None;let(storage,birth)=semio_framework_value::OriginalFailureStorage::admit(semio_framework_value::OriginalFailureStorage::birth_bytes(),&mut actual).result.unwrap();assert_eq!(actual,Some(semio_framework_value::OriginalFailureStorage::birth_bytes()));assert_eq!(birth.retained_capacity_bytes,actual.unwrap());let original=storage.attach_owned_parts(inner,None,Some(value("outerWork")),None,None).with_retained_progress(RetainedCloneProgress{copied_bytes:11,..Default::default()});
 for row in fixture["sourceDepthCases"].as_array().unwrap(){let depth=row["depth"].as_u64().unwrap()as usize;let accepted=row["accepted"].as_bool().unwrap();assert_eq!(accepted,depth>=fixture["nodes"].as_u64().unwrap()as usize);let mut observer=|_|true;let mut allocations=0usize;let mut allocate=|_:semio_framework_value::native_encoding::NativeAllocationEvent|{allocations+=1;Ok(())};let mut action=|_:usize,_:usize|Ok(());let mut allocation_loan_issuer=semio_framework_value::native_encoding::NativeEncodeAllocationIssuer::new();let mut allocation_loan=allocation_loan_issuer.scoped_loan(&mut allocate);let mut control=semio_framework_value::NativeEncodeControl::new_scoped_source(65536,depth,&mut observer,&mut allocation_loan,&mut action);let error=semio_framework_io_failure_owner::retirement_value(&original,&mut control).unwrap_err();assert_eq!(error.kind,if accepted{ValueRefusalKind::UnsupportedOwner}else{ValueRefusalKind::DepthLimit});drop(control);drop(allocation_loan);drop(allocate);if !accepted{assert_eq!(allocations,0)}}
 for row in fixture["enclosingDepthCases"].as_array().unwrap(){let depth=row["depth"].as_u64().unwrap()as usize;let accepted=row["accepted"].as_bool().unwrap();assert_eq!(accepted,depth>=fixture["nodes"].as_u64().unwrap()as usize+1);let mut observer=|_|true;let mut allocate=|_:semio_framework_value::native_encoding::NativeAllocationEvent|Ok(());let mut action=|_:usize,_:usize|Ok(());let mut allocation_loan_issuer=semio_framework_value::native_encoding::NativeEncodeAllocationIssuer::new();let mut allocation_loan=allocation_loan_issuer.scoped_loan(&mut allocate);let mut control=semio_framework_value::NativeEncodeControl::new_scoped_source(65536,depth,&mut observer,&mut allocation_loan,&mut action);let error=control.scoped_depth(usize::MAX,|control|semio_framework_io_failure_owner::retirement_value(&original,control)).unwrap_err();assert_eq!(error.kind,if accepted{ValueRefusalKind::UnsupportedOwner}else{ValueRefusalKind::DepthLimit});}
 let mut observer=|_|true;let mut control=semio_framework_value::NativeEncodeControl::new(65536,&mut observer);let projected=semio_framework_io_failure_owner::retirement_value(&original,&mut control).unwrap();let json=serde_json::to_value(&projected).unwrap();assert_eq!(json["progressOverride"]["copiedBytes"],11);assert_eq!(json["child"]["progressOverride"]["copiedBytes"],7);assert_eq!(json["workRefusal"]["message"],fixture["outerWork"]);assert_eq!(json["child"]["primary"]["message"],fixture["innerPrimary"]);assert_eq!(json["child"]["workRefusal"]["message"],fixture["innerWork"]);assert_eq!(json["child"]["receiptRefusal"]["message"],fixture["innerReceipt"]);assert_eq!(json["child"]["allocationRefusal"]["message"],fixture["innerAllocation"]);drop(control);let grant=semio_framework_value::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:4096};close(projected,grant,4096);close(original,grant,4096);
}

#[test]
fn receiving_wire_retains_each_allocation_cause_and_physical_progress(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🛂️receiving-allocation.json")).unwrap();let names=fixture["channels"].as_array().unwrap();let owned=|i:usize|ValueError::new(ValueRefusalKind::Canceled,names[i].as_str().unwrap().to_owned());let grant=semio_framework_value::RetainedCloneGrant{maximum_items:100000,maximum_copy_bytes:1048576,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:4096};for actual in fixture["actualCapacityCases"].as_array().unwrap(){let mut receiving=OriginalReceivingPrimary{retirement_failure:Some(semio_framework_value::OriginalRetirementFailure::from_causes(Some(ValueError::new(ValueRefusalKind::Canceled,"nested retirement".to_owned())),None,None,Some(ValueError::new(ValueRefusalKind::Canceled,"nested allocation".to_owned()).into()))),work_refusal:Some(ValueError::new(ValueRefusalKind::WorkLimit,fixture["workRefusal"].as_str().unwrap().to_owned())),work_overrun:Some(ValueError::new(ValueRefusalKind::WorkLimit,fixture["workOverrun"].as_str().unwrap().to_owned())),primary:None,quote_refusal:None,allocation_refusal:None,allocation_failure:Some(Default::default()),native_allocation:Some(semio_framework_value_native_owned::native_decoding::NativeDecodeAllocationOutcome{request:None,admitted:true,quote_refusal:Some(owned(3).into()),primary:Some(owned(0)),extent_refusal:Some(owned(1)),settlement_refusal:Some(owned(2).into()),actual:Some(0)}),receipt_refusal:Some(ValueError::new(ValueRefusalKind::Canceled,fixture["receipt"].as_str().unwrap().to_owned())),progress:Default::default()};let allocation=receiving.allocation_failure.as_mut().unwrap();allocation.primary=Some(owned(0));allocation.admission=Some(owned(1));allocation.forwarded_admission=Some(owned(2).into());allocation.scoped_admission=Some(owned(3).into());allocation.forwarded_quote=Some(owned(4).into());allocation.scoped_quote=Some(owned(5).into());allocation.forwarded_post=Some(owned(6).into());allocation.scoped_post=Some(owned(7).into());allocation.forwarded_cancel=Some(owned(8).into());allocation.scoped_cancel=Some(owned(9).into());allocation.receipt=Some(owned(10));allocation.extent=Some(owned(11));allocation.progress.prior_admitted_bytes=(!actual.is_null()).then(||fixture["priorAdmittedBytes"].as_u64().unwrap()as usize);allocation.progress.requested_bytes=(!actual.is_null()).then(||fixture["requestedBytes"].as_u64().unwrap()as usize);allocation.progress.maximum_bytes=(!actual.is_null()).then(||fixture["maximumBytes"].as_u64().unwrap()as usize);allocation.progress.admitted_bytes=fixture["admittedBytes"].as_u64().unwrap()as usize;allocation.progress.actual_capacity_bytes=actual.as_u64().map(|v|v as usize);let original_overrun=receiving.work_overrun.as_ref().unwrap().message.as_ptr();let original=NativeSnapshotFailure::from(receiving);assert_eq!(original.receiving_primary().unwrap().work_overrun.as_ref().unwrap().message.as_ptr(),original_overrun);assert_eq!(original.receipt_refusal().unwrap().message.as_ref(),fixture["receipt"].as_str().unwrap());let mut observe=|_|true;let mut encoder=semio_framework_value::NativeEncodeControl::new(grant.maximum_capacity_bytes,&mut observe);let wire=original.to_value_controlled(&mut encoder).unwrap();drop(encoder);let json=serde_json::to_value(&wire).unwrap();assert_eq!(json["cause"]["workRefusal"]["message"],fixture["workRefusal"]);assert_eq!(json["cause"]["workOverrun"]["message"],fixture["workOverrun"]);assert_eq!(json["cause"]["retirementFailure"]["primary"]["message"],"nested retirement");assert_eq!(json["cause"]["retirementFailure"]["allocationRefusal"]["message"],"nested allocation");for name in names{let name=name.as_str().unwrap();assert_eq!(json["cause"]["allocationFailure"][name]["message"],name)}assert_eq!(json["cause"]["allocationFailure"]["progress"]["actualCapacityBytes"],*actual);let decoded=receive_wire(wire);assert_eq!(decoded.receiving_primary().unwrap().work_refusal.as_ref().unwrap().message,fixture["workRefusal"].as_str().unwrap());assert_eq!(decoded.receiving_primary().unwrap().work_overrun.as_ref().unwrap().message,fixture["workOverrun"].as_str().unwrap());assert_eq!(decoded,original);close(decoded,grant,100000);close(original,grant,100000);}}

#[test]
fn incomplete_allocation_request_refuses_encoding_without_moving_its_owner(){let mut receiving=OriginalReceivingPrimary{retirement_failure:None,work_refusal:None,work_overrun:None,primary:None,quote_refusal:None,allocation_refusal:None,allocation_failure:Some(Default::default()),native_allocation:None,receipt_refusal:None,progress:Default::default()};receiving.allocation_failure.as_mut().unwrap().progress.requested_bytes=Some(73);let failure=NativeSnapshotFailure::from(receiving);let mut observer=|_|true;let mut encoder=semio_framework_value::NativeEncodeControl::new(65536,&mut observer);assert!(failure.to_value_controlled(&mut encoder).is_err());assert_eq!(failure.receiving_primary().unwrap().allocation_failure.as_ref().unwrap().progress.requested_bytes,Some(73));drop(encoder);close(failure,semio_framework_value::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:128},4096);}

#[test]fn encode_effect_failure_retains_every_original_cause_and_projects_wire(){use semio_framework_value::native_encoding::{NativeAllocationRequest,NativeEncodeAllocationOutcome,NativeEncodeEffectFailure};let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🎟️encode-effect.json")).unwrap();let source=&fixture["encodeEffect"];let error=|v:&serde_json::Value|Some(ValueError::new(ValueRefusalKind::Canceled,v["message"].as_str().unwrap().to_owned()));let a=&source["allocation"];let request=&a["request"];let effect=NativeEncodeEffectFailure{primary:error(&source["primary"]),context:error(&source["context"]),invariant:error(&source["invariant"]),physical_invariant:error(&source["physicalInvariant"]),capacity_invariant:error(&source["capacityInvariant"]),marker_failure:error(&source["markerFailure"]),work:error(&source["work"]),work_overrun:error(&source["workOverrun"]),local:error(&source["local"]),physical:error(&source["physical"]),allocation:Some(NativeEncodeAllocationOutcome{request:Some(NativeAllocationRequest{bytes:request["bytes"].as_u64().unwrap()as usize,owned_bytes:request["ownedBytes"].as_u64().unwrap()as usize,next_owned_bytes:request["nextOwnedBytes"].as_u64().unwrap()as usize,maximum_bytes:request["maximumBytes"].as_u64().unwrap()as usize}),admitted:a["admitted"].as_bool().unwrap(),primary:error(&a["primary"]),forwarded_quote:error(&a["forwardedQuote"]).map(Into::into),scoped_quote:error(&a["scopedQuote"]).map(Into::into),extent_refusal:error(&a["extentRefusal"]),forwarded_refusal:error(&a["forwardedRefusal"]).map(Into::into),scoped_refusal:error(&a["scopedRefusal"]).map(Into::into),actual:a["actual"].as_u64().map(|v|v as usize)})};let pointers=[effect.primary.as_ref().unwrap().message.as_ptr(),effect.context.as_ref().unwrap().message.as_ptr(),effect.invariant.as_ref().unwrap().message.as_ptr(),effect.physical_invariant.as_ref().unwrap().message.as_ptr(),effect.capacity_invariant.as_ref().unwrap().message.as_ptr(),effect.marker_failure.as_ref().unwrap().message.as_ptr(),effect.work.as_ref().unwrap().message.as_ptr(),effect.work_overrun.as_ref().unwrap().message.as_ptr(),effect.local.as_ref().unwrap().message.as_ptr(),effect.physical.as_ref().unwrap().message.as_ptr(),effect.allocation.as_ref().unwrap().scoped_refusal.as_ref().unwrap().owned().unwrap().message.as_ptr()];let failure=NativeSnapshotFailure::from_encode_effect(effect,RetainedCloneProgress::default());let effect=failure.encode_effect().unwrap();assert_eq!([effect.primary.as_ref().unwrap().message.as_ptr(),effect.context.as_ref().unwrap().message.as_ptr(),effect.invariant.as_ref().unwrap().message.as_ptr(),effect.physical_invariant.as_ref().unwrap().message.as_ptr(),effect.capacity_invariant.as_ref().unwrap().message.as_ptr(),effect.marker_failure.as_ref().unwrap().message.as_ptr(),effect.work.as_ref().unwrap().message.as_ptr(),effect.work_overrun.as_ref().unwrap().message.as_ptr(),effect.local.as_ref().unwrap().message.as_ptr(),effect.physical.as_ref().unwrap().message.as_ptr(),effect.allocation.as_ref().unwrap().scoped_refusal.as_ref().unwrap().owned().unwrap().message.as_ptr()],pointers);let mut observe=|_|true;let mut native=semio_framework_value::NativeEncodeControl::new(1<<20,&mut observe);let wire=failure.to_value_controlled(&mut native).unwrap();assert_eq!(serde_json::to_value(&wire).unwrap(),fixture);drop(native);let grant=semio_framework_value::RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:4096};let decoded=receive_wire(wire);assert_eq!(decoded,failure);close(decoded,grant,100000);close(failure,grant,100000);}

#[test]fn retained_allocation_refusal_stays_with_its_original_vault_during_wire_projection(){use semio_framework_value::RetainedCloneGrant;use semio_framework_value_control_contract::{NativeAllocationRefusal,NativeAllocationRefusalVault};let mut vault=NativeAllocationRefusalVault::default();let original=ValueError::new(ValueRefusalKind::Canceled,"original allocation owner".to_owned());let pointer=original.message.as_ptr();let handle=vault.retain(original).unwrap();let refusal=NativeAllocationRefusal::Retained(handle);let mut callback=|_|true;let mut control=semio_framework_value::NativeEncodeControl::new(4096,&mut callback);let error=semio_framework_io_failure_owner::optional_refusal(Some(&refusal),&mut control).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::UnsupportedOwner);drop(control);let NativeAllocationRefusal::Retained(handle)=refusal else{unreachable!()};let original=vault.take(handle).unwrap();assert_eq!(original.message.as_ptr(),pointer);let grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};close(error,grant,1024);close(original,grant,1024);}

#[test]fn owned_allocation_refusal_projects_wire_without_moving_original(){use semio_framework_value::RetainedCloneGrant;use semio_framework_value_control_contract::NativeAllocationRefusal;let original=ValueError::new(ValueRefusalKind::Canceled,"owned allocation refusal".to_owned());let pointer=original.message.as_ptr();let refusal=NativeAllocationRefusal::Owned(original);let mut callback=|_|true;let mut control=semio_framework_value::NativeEncodeControl::new(4096,&mut callback);let wire=semio_framework_io_failure_owner::optional_refusal(Some(&refusal),&mut control).unwrap();drop(control);let NativeAllocationRefusal::Owned(original)=refusal else{unreachable!()};assert_eq!(original.message.as_ptr(),pointer);let grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};close(wire,grant,1024);close(original,grant,1024);}

#[test]
fn staged_recursive_retirement_preserves_each_original_cause(){
 let wire:semio_framework_value::DslValue=serde_json::from_str(include_str!("🧫️fixtures/♻️recursive-retirement.json")).unwrap();
 let failure=receive_wire(wire);let outer=failure.retirement_failure().unwrap();let inner=outer.child().unwrap();
 for(node,prefix)in[(outer,"outer"),(inner,"inner")]{assert_eq!(node.primary().unwrap().message,format!("{prefix} primary"));assert_eq!(node.work_refusal().unwrap().message,format!("{prefix} work"));assert_eq!(node.receipt_refusal().unwrap().message,format!("{prefix} receipt"));assert_eq!(node.allocation_refusal().unwrap().owned().unwrap().message,format!("{prefix} allocation"));assert_eq!(node.retained_progress().copied_bytes,3);}
 assert!(inner.child().is_none());let grant=semio_framework_value::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:1048576,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:4096};close(failure,grant,1000000);
}
/// 🪢️ Native receiving keeps its actual retirement owner through the closed snapshot codec.
#[test]
fn receiving_retirement_is_not_erased_by_wire_or_equality(){let primary=semio_framework_value::OriginalRetirementFailure::from_causes(Some(ValueError::literal(ValueRefusalKind::InvalidValue,"original inner retirement 源")),Some(ValueError::literal(ValueRefusalKind::WorkLimit,"independent inner work")),Some(ValueError::literal(ValueRefusalKind::Canceled,"independent inner receipt")),None);let mut receiving=OriginalReceivingPrimary::from(primary);receiving.work_refusal=Some(ValueError::literal(ValueRefusalKind::WorkLimit,"outer receiving work"));let original=NativeSnapshotFailure::from(receiving);let grant=semio_framework_value::RetainedCloneGrant{maximum_items:65536,maximum_copy_bytes:1048576,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:4096};let mut observe=|_|true;let mut native=semio_framework_value::NativeEncodeControl::new(1048576,&mut observe);let wire=original.to_value_controlled(&mut native).unwrap();drop(native);let json=serde_json::to_value(&wire).unwrap();assert_eq!(json["cause"]["retirementFailure"]["primary"]["message"],"original inner retirement 源");assert_eq!(json["cause"]["workRefusal"]["message"],"outer receiving work");let decoded=receive_wire(wire);assert_eq!(decoded,original);assert!(decoded.receiving_primary().unwrap().retirement_failure.is_some());close(decoded,grant,100000);close(original,grant,100000);close(wire,grant,100000);}
